/* @lc app=leetcode id=3203 lang=kotlin */
class Solution { fun minimumDiameterAfterMerge(edges1: Array<IntArray>, edges2: Array<IntArray>): Int = ({ edges: Array<IntArray> -> (edges.size + 1).let { n -> Array(n) { mutableListOf<Int>() }.also { adj -> edges.forEach { adj[it[0]].add(it[1]).also { adj[it[1]].add(it[0]) } } }.let { adj -> { start: Int -> generateSequence(listOf(start) to IntArray(n) { -1 }.also { it[start] = 0 }) { pair -> pair.let { (curr, dist) -> curr.flatMap { u -> adj[u].map { v -> u to v } }.filter { dist[it.second] == -1 }.distinctBy { it.second }.onEach { p -> dist[p.second] = dist[p.first] + 1 }.map { it.second }.takeIf { it.isNotEmpty() }?.let { it to dist } } }.last().let { pair -> pair.first.first().let { lastNode -> lastNode to pair.second[lastNode] } } }.let { bfs -> bfs(bfs(0).first).second } } }).let { getDia -> getDia(edges1).let { d1 -> getDia(edges2).let { d2 -> maxOf(d1, d2, (d1 + 1) / 2 + (d2 + 1) / 2 + 1) } } } }